const $=s=>document.querySelector(s);
export const DANCES=[{id:'sway',name:'Lắc lư',emoji:'🌷',bpm:88},{id:'disco',name:'Nhún nhảy',emoji:'🪩',bpm:112},{id:'ballet',name:'Xoay nhẹ',emoji:'🩰',bpm:72}];

export function installMayShow({getState,say,react}){
 const garden=$('#garden'),mascot=$('#mascot');let dance='sway',running=false,music=false,audio=null,ticker=null,nextBeat=0,step=0,musicGeneration=0;
 garden.insertAdjacentHTML('afterbegin',`<div class="stage-set" aria-hidden="true"><svg viewBox="0 0 1200 650" preserveAspectRatio="xMidYMid slice"><defs><linearGradient id="stage-sky" x2="0" y2="1"><stop stop-color="#74729b"/><stop offset="1" stop-color="#b6a5c5"/></linearGradient><radialGradient id="stage-glow"><stop stop-color="#fff3d8" stop-opacity=".7"/><stop offset="1" stop-color="#fff3d8" stop-opacity="0"/></radialGradient><linearGradient id="stage-floor" x2="0" y2="1"><stop stop-color="#edc6c7"/><stop offset="1" stop-color="#c7add2"/></linearGradient></defs><rect width="1200" height="650" fill="url(#stage-sky)"/><circle cx="600" cy="270" r="330" fill="url(#stage-glow)"/><path d="M0 65Q600 210 1200 65" fill="none" stroke="#e8d9bd" stroke-width="3"/>${Array.from({length:13},(_,i)=>`<circle cx="${i*100}" cy="${65+Math.sin(i/12*Math.PI)*72}" r="9" fill="${['#ffe9af','#f5d0df','#e4d8f6'][i%3]}"/>`).join('')}<ellipse cx="600" cy="560" rx="570" ry="210" fill="url(#stage-floor)"/><ellipse cx="600" cy="500" rx="310" ry="89" fill="#f3d7cc" stroke="#f7e7d8" stroke-width="5"/><path d="M0 0h155q-55 100 0 205l-80 25L0 650ZM1200 0h-155q55 100 0 205l80 25 75 420Z" fill="#d7a9c5"/><path d="M30 0q90 130 0 410M1170 0q-90 130 0 410" fill="none" stroke="#c294b7" stroke-width="20"/><path d="M535 224q-32 2-32-23 0-24 25-24 2-30 31-24 24-26 43 4 37-12 39 22 29 6 20 31-5 18-30 15Z" fill="#fcf2ed" opacity=".7"/><path d="m340 260 7 18 19 2-15 12 4 19-15-10-16 10 5-19-15-12 19-2ZM855 218l5 12 14 2-11 9 4 13-12-7-11 7 3-13-10-9 13-2Z" fill="#f9e9b1" opacity=".8"/></svg><div class="stage-confetti">${Array.from({length:14},(_,i)=>`<i style="--i:${i}">${['✦','♡','♪'][i%3]}</i>`).join('')}</div></div>`);
 garden.insertAdjacentHTML('beforeend',`<section class="show-controls" aria-label="Sân khấu Mây"><span class="show-eyebrow">MỘT TIẾT MỤC NHỎ CHO BẠN</span><div class="dance-choices">${DANCES.map(d=>`<button data-dance="${d.id}" aria-pressed="${d.id===dance}"><span>${d.emoji}</span><small>${d.name}</small></button>`).join('')}</div><button id="dance-toggle" class="dance-toggle" aria-pressed="false">▶ Nhảy nào</button><button id="dance-music" class="dance-music" aria-pressed="false">♫ Bật nhạc</button><p id="dance-note">Chạm Mây để đổi điệu.</p></section>`);
 function current(){return DANCES.find(d=>d.id===dance);}
 function reduced(){return !getState().motion||matchMedia('(prefers-reduced-motion: reduce)').matches;}
 function render(){garden.dataset.dance=dance;garden.dataset.dancing=running;garden.style.setProperty('--dance-beat',`${60/current().bpm}s`);document.querySelectorAll('[data-dance]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.dance===dance));$('#dance-toggle').textContent=running?'Ⅱ Nghỉ một chút':'▶ Nhảy nào';$('#dance-toggle').setAttribute('aria-pressed',running);$('#dance-music').textContent=music?'♫ Tắt nhạc':'♫ Bật nhạc';$('#dance-music').setAttribute('aria-pressed',music);$('#dance-note').textContent=reduced()?'Chuyển động đang tạm dừng theo lựa chọn của bạn.':'Chạm Mây để đổi điệu.';}
 function stop(){running=false;musicGeneration++;clearInterval(ticker);ticker=null;if(audio)audio.master.gain.setTargetAtTime(0,audio.ctx.currentTime,.04);render();}
 function ensureAudio(){if(audio)return;const C=window.AudioContext||window.webkitAudioContext;if(!C)throw new Error('audio');const ctx=new C(),master=ctx.createGain();master.gain.value=0;master.connect(ctx.destination);audio={ctx,master};}
 function note(f,time,duration,volume,type='sine'){const o=audio.ctx.createOscillator(),g=audio.ctx.createGain();o.type=type;o.frequency.value=f;g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(volume,time+.018);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(audio.master);o.start(time);o.stop(time+duration+.02);}
 function schedule(){if(!music||!running||!audio)return;const melody=[523.25,659.25,783.99,659.25,587.33,659.25,523.25,392];while(nextBeat<audio.ctx.currentTime+.15){note(melody[step%8],nextBeat,.22,.1,'triangle');if(step%2===0)note([130.81,164.81,146.83,174.61][Math.floor(step/4)%4],nextBeat,.35,.16);step++;nextBeat+=60/current().bpm/2;}}
 function startMusic(){const gen=++musicGeneration;clearInterval(ticker);ticker=null;if(!music||!running){if(audio)audio.master.gain.setTargetAtTime(0,audio.ctx.currentTime,.04);return;}try{ensureAudio();audio.ctx.resume().then(()=>{if(gen!==musicGeneration||!running||!music||document.hidden)return;audio.master.gain.setTargetAtTime(.32,audio.ctx.currentTime,.06);step=0;nextBeat=audio.ctx.currentTime+.06;schedule();ticker=setInterval(schedule,60);}).catch(()=>{if(gen===musicGeneration){music=false;render();$('#dance-note').textContent='Chưa mở được âm thanh; Mây vẫn nhảy được.';}});}catch{music=false;render();$('#dance-note').textContent='Chưa mở được âm thanh; Mây vẫn nhảy được.';}}
 function choose(id){if(!DANCES.some(d=>d.id===id))return;dance=id;render();if(running)startMusic();if(document.body.dataset.scene==='stage')say(`${current().emoji} ${current().name} cùng Mây nhé!`,'wave');}
 $('#dance-toggle').addEventListener('click',()=>{if(running){stop();return;}if(reduced()){render();$('#status').textContent='Hãy bật chuyển động nếu bạn muốn xem Mây nhảy.';return;}running=true;render();say('Không cần nhảy đúng nhịp. Mình vui một chút thôi!','happy');startMusic();});
 $('#dance-music').addEventListener('click',()=>{music=!music;render();startMusic();});
 document.querySelectorAll('[data-dance]').forEach(b=>b.addEventListener('click',()=>choose(b.dataset.dance)));
 mascot.addEventListener('click',e=>{if(document.body.dataset.scene!=='stage'||e.target.closest('.show-controls'))return;e.stopImmediatePropagation();const i=DANCES.findIndex(d=>d.id===dance);choose(DANCES[(i+1)%DANCES.length].id);},{capture:true});
 document.addEventListener('may-scene',()=>{stop();if(document.body.dataset.scene==='stage'){say('Mây có một tiết mục nhỏ. Bạn chọn điệu nha.','wave');}});
 $('#motion').addEventListener('click',()=>queueMicrotask(()=>{if(reduced())stop();else render();}));
 matchMedia('(prefers-reduced-motion: reduce)').addEventListener('change',()=>{if(reduced())stop();});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
 render();return {stop};
}
